CREATE SCHEMA IF NOT EXISTS extensions;
CREATE EXTENSION IF NOT EXISTS postgis WITH SCHEMA extensions;
CREATE TYPE public.app_role AS ENUM ('client','installer','admin');
CREATE TABLE public.profiles (id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE, full_name text NOT NULL DEFAULT '', phone text NOT NULL DEFAULT '', avatar_path text, show_exact_address boolean NOT NULL DEFAULT false, allow_messages boolean NOT NULL DEFAULT false, notifications boolean NOT NULL DEFAULT true, service_radius integer NOT NULL DEFAULT 25, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT, UPDATE ON public.profiles TO authenticated; GRANT ALL ON public.profiles TO service_role;
ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;
CREATE POLICY profiles_own_read ON public.profiles FOR SELECT TO authenticated USING (id=auth.uid());
CREATE POLICY profiles_own_update ON public.profiles FOR UPDATE TO authenticated USING (id=auth.uid()) WITH CHECK (id=auth.uid());
CREATE TABLE public.user_roles (user_id uuid REFERENCES auth.users(id) ON DELETE CASCADE, role public.app_role NOT NULL DEFAULT 'client', PRIMARY KEY(user_id,role));
GRANT SELECT ON public.user_roles TO authenticated; GRANT ALL ON public.user_roles TO service_role;
ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY;
CREATE POLICY roles_own_read ON public.user_roles FOR SELECT TO authenticated USING (user_id=auth.uid());
CREATE FUNCTION public.has_role(_user_id uuid,_role public.app_role) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=_user_id AND role=_role) $$;
CREATE FUNCTION public.create_profile() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN INSERT INTO public.profiles(id,full_name) VALUES (NEW.id,coalesce(NEW.raw_user_meta_data->>'full_name',NEW.raw_user_meta_data->>'name','')); INSERT INTO public.user_roles(user_id,role) VALUES(NEW.id,'client'); RETURN NEW; END $$;
CREATE TRIGGER holidayfx_new_user AFTER INSERT ON auth.users FOR EACH ROW EXECUTE FUNCTION public.create_profile();
CREATE TABLE public.bookings (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), client_id uuid NOT NULL REFERENCES public.profiles(id), installer_id uuid REFERENCES public.profiles(id), address text NOT NULL, geo_location extensions.geography(Point,4326), roof_linear_feet integer NOT NULL, complexity_tier integer NOT NULL CHECK(complexity_tier BETWEEN 1 AND 3), extras jsonb NOT NULL DEFAULT '{}', estimated_cost numeric(10,2) NOT NULL, deposit numeric(10,2) NOT NULL, scheduled_date date NOT NULL, status text NOT NULL DEFAULT 'quoted' CHECK(status IN ('quoted','pending','confirmed','in_progress','completed','cancelled')), created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.bookings TO authenticated; GRANT ALL ON public.bookings TO service_role;
ALTER TABLE public.bookings ENABLE ROW LEVEL SECURITY;
CREATE POLICY bookings_read ON public.bookings FOR SELECT TO authenticated USING(client_id=auth.uid() OR installer_id=auth.uid() OR public.has_role(auth.uid(),'admin'));
CREATE INDEX bookings_geo ON public.bookings USING gist(geo_location);
CREATE TABLE public.map_pins (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES public.profiles(id), title text NOT NULL, description text NOT NULL DEFAULT '', address text NOT NULL, longitude double precision NOT NULL CHECK(longitude BETWEEN -180 AND 180), latitude double precision NOT NULL CHECK(latitude BETWEEN -90 AND 90), geo_location extensions.geography(Point,4326), display_schedule text NOT NULL DEFAULT '', image_path text, is_verified_commercial boolean NOT NULL DEFAULT false, award_winner boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,DELETE ON public.map_pins TO authenticated; GRANT SELECT ON public.map_pins TO anon; GRANT ALL ON public.map_pins TO service_role;
ALTER TABLE public.map_pins ENABLE ROW LEVEL SECURITY;
CREATE POLICY pins_public ON public.map_pins FOR SELECT TO anon,authenticated USING(true);
CREATE POLICY pins_create ON public.map_pins FOR INSERT TO authenticated WITH CHECK(user_id=auth.uid() AND NOT is_verified_commercial AND NOT award_winner);
CREATE POLICY pins_delete ON public.map_pins FOR DELETE TO authenticated USING(user_id=auth.uid());
CREATE INDEX pins_geo ON public.map_pins USING gist(geo_location);
CREATE FUNCTION public.pin_location() RETURNS trigger LANGUAGE plpgsql SET search_path=public,extensions AS $$ BEGIN NEW.geo_location=extensions.ST_SetSRID(extensions.ST_MakePoint(NEW.longitude,NEW.latitude),4326)::extensions.geography; RETURN NEW; END $$;
CREATE TRIGGER pin_location BEFORE INSERT OR UPDATE ON public.map_pins FOR EACH ROW EXECUTE FUNCTION public.pin_location();
CREATE TABLE public.posts (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES public.profiles(id), author_name text NOT NULL, map_pin_id uuid REFERENCES public.map_pins(id) ON DELETE SET NULL, image_path text NOT NULL, caption text NOT NULL DEFAULT '', created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,DELETE ON public.posts TO authenticated; GRANT SELECT ON public.posts TO anon; GRANT ALL ON public.posts TO service_role;
ALTER TABLE public.posts ENABLE ROW LEVEL SECURITY;
CREATE POLICY posts_public ON public.posts FOR SELECT TO anon,authenticated USING(true);
CREATE POLICY posts_create ON public.posts FOR INSERT TO authenticated WITH CHECK(user_id=auth.uid());
CREATE POLICY posts_delete ON public.posts FOR DELETE TO authenticated USING(user_id=auth.uid());
CREATE TABLE public.post_likes(user_id uuid NOT NULL REFERENCES public.profiles(id),post_id uuid NOT NULL REFERENCES public.posts(id) ON DELETE CASCADE, PRIMARY KEY(user_id,post_id));
GRANT SELECT,INSERT,DELETE ON public.post_likes TO authenticated; GRANT SELECT ON public.post_likes TO anon; GRANT ALL ON public.post_likes TO service_role;
ALTER TABLE public.post_likes ENABLE ROW LEVEL SECURITY;
CREATE POLICY likes_read ON public.post_likes FOR SELECT TO anon,authenticated USING(true);
CREATE POLICY likes_add ON public.post_likes FOR INSERT TO authenticated WITH CHECK(user_id=auth.uid());
CREATE POLICY likes_remove ON public.post_likes FOR DELETE TO authenticated USING(user_id=auth.uid());
CREATE TABLE public.post_comments(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES public.profiles(id),post_id uuid NOT NULL REFERENCES public.posts(id) ON DELETE CASCADE,author_name text NOT NULL,content text NOT NULL CHECK(length(content) BETWEEN 1 AND 2000),created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,DELETE ON public.post_comments TO authenticated; GRANT SELECT ON public.post_comments TO anon; GRANT ALL ON public.post_comments TO service_role;
ALTER TABLE public.post_comments ENABLE ROW LEVEL SECURITY;
CREATE POLICY comments_read ON public.post_comments FOR SELECT TO anon,authenticated USING(true);
CREATE POLICY comments_add ON public.post_comments FOR INSERT TO authenticated WITH CHECK(user_id=auth.uid());
CREATE POLICY comments_remove ON public.post_comments FOR DELETE TO authenticated USING(user_id=auth.uid());
CREATE TABLE public.pin_votes(user_id uuid NOT NULL REFERENCES public.profiles(id),pin_id uuid NOT NULL REFERENCES public.map_pins(id) ON DELETE CASCADE, PRIMARY KEY(user_id,pin_id));
GRANT SELECT,INSERT,DELETE ON public.pin_votes TO authenticated; GRANT SELECT ON public.pin_votes TO anon; GRANT ALL ON public.pin_votes TO service_role;
ALTER TABLE public.pin_votes ENABLE ROW LEVEL SECURITY;
CREATE POLICY votes_read ON public.pin_votes FOR SELECT TO anon,authenticated USING(true);
CREATE POLICY votes_add ON public.pin_votes FOR INSERT TO authenticated WITH CHECK(user_id=auth.uid());
CREATE POLICY votes_remove ON public.pin_votes FOR DELETE TO authenticated USING(user_id=auth.uid());
CREATE POLICY photos_read ON storage.objects FOR SELECT TO anon,authenticated USING(bucket_id='holiday-photos');
CREATE POLICY photos_upload ON storage.objects FOR INSERT TO authenticated WITH CHECK(bucket_id='holiday-photos' AND (storage.foldername(name))[1]=auth.uid()::text);
CREATE POLICY photos_delete ON storage.objects FOR DELETE TO authenticated USING(bucket_id='holiday-photos' AND (storage.foldername(name))[1]=auth.uid()::text);